import{_ as c,C as d,o,c as u,a2 as i,b as r,w as e,a as n,E as s,a3 as l}from"./chunks/framework.CgxQ0r6v.js";const I=JSON.parse('{"title":"Manual de Estudio Profundo: Evaluación 2","description":"","frontmatter":{},"headers":[],"relativePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-VI/Lectura_Catedra_Evaluacion_2.md","filePath":"materias/Proyecto_Sociotecnologico_II/documentacion/II-VI/Lectura_Catedra_Evaluacion_2.md"}'),p={name:"materias/Proyecto_Sociotecnologico_II/documentacion/II-VI/Lectura_Catedra_Evaluacion_2.md"};function m(g,a,f,h,A,E){const t=d("Mermaid");return o(),u("div",null,[a[2]||(a[2]=i('<h1 id="manual-de-estudio-profundo-evaluacion-2" tabindex="-1">Manual de Estudio Profundo: Evaluación 2 <a class="header-anchor" href="#manual-de-estudio-profundo-evaluacion-2" aria-label="Permalink to &quot;Manual de Estudio Profundo: Evaluación 2&quot;">​</a></h1><h2 id="materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-vi" tabindex="-1">Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre VI) <a class="header-anchor" href="#materia-proyecto-sociotecnologico-ii-trayecto-ii-trimestre-vi" aria-label="Permalink to &quot;Materia: Proyecto Sociotecnológico II (Trayecto II - Trimestre VI)&quot;">​</a></h2><h3 id="eje-tematico-estrategia-de-implantacion-y-capacitacion-a-usuarios" tabindex="-1">Eje Temático: Estrategia de Implantación y Capacitación a Usuarios <a class="header-anchor" href="#eje-tematico-estrategia-de-implantacion-y-capacitacion-a-usuarios" aria-label="Permalink to &quot;Eje Temático: Estrategia de Implantación y Capacitación a Usuarios&quot;">​</a></h3><hr><h2 id="🧭-introduccion-la-llegada-del-software-a-su-hogar-definitivo" tabindex="-1">🧭 Introducción: La Llegada del Software a su Hogar Definitivo <a class="header-anchor" href="#🧭-introduccion-la-llegada-del-software-a-su-hogar-definitivo" aria-label="Permalink to &quot;🧭 Introducción: La Llegada del Software a su Hogar Definitivo&quot;">​</a></h2><p>La <strong>implantación</strong> (o despliegue) es la fase en la cual la aplicación informática deja de ser un proyecto confinado a las computadoras de los estudiantes para instalarse, configurarse y comenzar a operar en los equipos definitivos de la comunidad u organización.</p><p>Sin embargo, el software no se implanta solo. La tecnología es inútil si las personas que deben operarla diariamente no saben cómo usarla o le tienen miedo. Por ello, la implantación en el PNFI es un proceso indisoluble entre <strong>dos dimensiones:</strong></p><ol><li><strong>La Dimensión Técnica:</strong> Instalación del servidor, migración de base de datos y configuración de red.</li><li><strong>La Dimensión Humana y Social:</strong> Transferencia tecnológica, capacitación a los operadores y acompañamiento presencial.</li></ol><hr><h2 id="🚀-capitulo-i-estrategias-de-implantacion-de-software" tabindex="-1">🚀 CAPÍTULO I: Estrategias de Implantación de Software <a class="header-anchor" href="#🚀-capitulo-i-estrategias-de-implantacion-de-software" aria-label="Permalink to &quot;🚀 CAPÍTULO I: Estrategias de Implantación de Software&quot;">​</a></h2><p>El equipo debe seleccionar una de las cuatro estrategias clásicas de implantación:</p>',11)),(o(),r(l,null,{default:e(()=>[s(t,{id:"mermaid-38",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20E%5B%22%F0%9F%9A%80%20Estrategias%20de%20Implantaci%C3%B3n%22%5D%0A%20%20%20%20E%20--%3E%20E1%5B%22%E2%9A%A1%20Implantaci%C3%B3n%20Directa%20(Corte%20Abrupto)%22%5D%0A%20%20%20%20E%20--%3E%20E2%5B%22%F0%9F%94%84%20Implantaci%C3%B3n%20en%20Paralelo%20(Recomendada%20en%20PST%20II)%22%5D%0A%20%20%20%20E%20--%3E%20E3%5B%22%F0%9F%8E%AF%20Implantaci%C3%B3n%20Piloto%22%5D%0A%20%20%20%20E%20--%3E%20E4%5B%22%F0%9F%93%B6%20Implantaci%C3%B3n%20por%20Fases%20%2F%20M%C3%B3dulos%22%5D%0A%0A%20%20%20%20style%20E%20fill%3A%231e293b%2Cstroke%3A%2364748b%2Ccolor%3A%23fff%0A%20%20%20%20style%20E1%20fill%3A%237c2d12%2Cstroke%3A%23ea580c%2Ccolor%3A%23fff%0A%20%20%20%20style%20E2%20fill%3A%2315803d%2Cstroke%3A%2322c55e%2Ccolor%3A%23fff%0A%20%20%20%20style%20E3%20fill%3A%230369a1%2Cstroke%3A%230ea5e9%2Ccolor%3A%23fff%0A%20%20%20%20style%20E4%20fill%3A%234338ca%2Cstroke%3A%236366f1%2Ccolor%3A%23fff%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i('<h3 id="_1-1-comparativa-de-estrategias" tabindex="-1">1.1 Comparativa de Estrategias <a class="header-anchor" href="#_1-1-comparativa-de-estrategias" aria-label="Permalink to &quot;1.1 Comparativa de Estrategias&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Estrategia</th><th>Descripción</th><th>Ventajas</th><th>Desventajas / Riesgos</th></tr></thead><tbody><tr><td><strong>Directa (Big Bang)</strong></td><td>Se apaga el sistema manual de papel en un día y se usa exclusivamente el nuevo software.</td><td>Rápida y sin duplicación de tareas.</td><td><strong>Muy Alto Riesgo:</strong> Si el sistema falla, la organización queda paralizada.</td></tr><tr><td><strong>En Paralelo (Recomendada)</strong></td><td>Durante 2 a 4 semanas, los operadores registran en el papel y simultáneamente en el nuevo software.</td><td><strong>Máxima Seguridad:</strong> Los datos están respaldados físicamente mientras los usuarios ganan confianza.</td><td>Duplica temporalmente la carga de trabajo de los operadores.</td></tr><tr><td><strong>Piloto</strong></td><td>Se implanta el sistema en una sola área o comisión (ej: solo en farmacia o solo en una vocería).</td><td>Permite corregir problemas en escala pequeña.</td><td>No prueba la integración de toda la organización.</td></tr><tr><td><strong>Por Fases</strong></td><td>Se libera módulo a módulo progresivamente (Módulo 1 en semana 1, Módulo 2 en semana 3).</td><td>Curva de aprendizaje suave para los operadores.</td><td>Requiere que el software esté fuertemente modularizado.</td></tr></tbody></table><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p><strong>Recomendación para PST II:</strong> En los consejos comunales e instituciones públicas de la región trujillana, <strong>la estrategia en paralelo es la más recomendada</strong>. Permite cotejar los resultados del sistema con los libros de papel y disipar cualquier duda sobre la fidelidad de los datos.</p></div><hr><h2 id="💾-capitulo-ii-preparacion-tecnica-del-entorno-y-migracion-de-datos" tabindex="-1">💾 CAPÍTULO II: Preparación Técnica del Entorno y Migración de Datos <a class="header-anchor" href="#💾-capitulo-ii-preparacion-tecnica-del-entorno-y-migracion-de-datos" aria-label="Permalink to &quot;💾 CAPÍTULO II: Preparación Técnica del Entorno y Migración de Datos&quot;">​</a></h2><h3 id="_2-1-despliegue-en-el-entorno-comunitario" tabindex="-1">2.1 Despliegue en el Entorno Comunitario <a class="header-anchor" href="#_2-1-despliegue-en-el-entorno-comunitario" aria-label="Permalink to &quot;2.1 Despliegue en el Entorno Comunitario&quot;">​</a></h3><p>La mayoría de las comunidades no cuentan con conexión a internet estable. Por lo tanto, el sistema debe configurarse como un <strong>servidor de red de área local (LAN)</strong>:</p><ul><li>Una de las computadoras comunitarias se designa como <strong>servidor local</strong> (con IP estática local, ej: <code>192.168.1.100</code>).</li><li>Se instala la pila de software libre requerida (Linux o Windows con Apache, PostgreSQL/MariaDB y PHP/Node/Python).</li><li>Las demás computadoras de la oficina se conectan mediante el navegador web apuntando a la IP del servidor.</li></ul><h3 id="_2-2-migracion-de-datos-historicos" tabindex="-1">2.2 Migración de Datos Históricos <a class="header-anchor" href="#_2-2-migracion-de-datos-historicos" aria-label="Permalink to &quot;2.2 Migración de Datos Históricos&quot;">​</a></h3><p>Un sistema vacío no es útil. Los estudiantes deben asistir a la comunidad en la digitalización de los datos activos:</p><ol><li>Depuración del censo en papel (eliminar registros duplicados o ilegibles).</li><li>Carga masiva mediante scripts SQL o plantillas CSV para que el sistema arranque con los datos reales de la comunidad.</li><li>Verificación de conteo y concordancia de registros.</li></ol><hr><h2 id="👥-capitulo-iii-plan-de-capacitacion-y-transferencia-tecnologica" tabindex="-1">👥 CAPÍTULO III: Plan de Capacitación y Transferencia Tecnológica <a class="header-anchor" href="#👥-capitulo-iii-plan-de-capacitacion-y-transferencia-tecnologica" aria-label="Permalink to &quot;👥 CAPÍTULO III: Plan de Capacitación y Transferencia Tecnológica&quot;">​</a></h2><p>La capacitación es la garantía de que el proyecto no morirá cuando los estudiantes aprueben la materia.</p><h3 id="_3-1-estructura-del-taller-de-capacitacion" tabindex="-1">3.1 Estructura del Taller de Capacitación <a class="header-anchor" href="#_3-1-estructura-del-taller-de-capacitacion" aria-label="Permalink to &quot;3.1 Estructura del Taller de Capacitación&quot;">​</a></h3><ul><li><strong>Sesión 1: Sensibilización y Conceptos Básicos:</strong> Explicar para qué sirve el sistema, cómo ingresar, cómo proteger su contraseña y la importancia de no apagar el servidor bruscamente.</li><li><strong>Sesión 2: Operaciones Cotidianas:</strong> Práctica guiada donde cada operador registra habitantes, busca datos y emite constancias con casos reales.</li><li><strong>Sesión 3: Manejo de Excepciones y Respaldos:</strong> Cómo restaurar una copia de seguridad y qué hacer si se produce un corte de energía eléctrica.</li></ul>',16)),(o(),r(l,null,{default:e(()=>[s(t,{id:"mermaid-200",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20Estudiante%20as%20Equipo%20PST%20II%0A%20%20%20%20actor%20Operador%20as%20Operador%20Comunitario%0A%20%20%20%20participant%20Sistema%20as%20Software%20Instalado%0A%0A%20%20%20%20Estudiante-%3E%3EOperador%3A%20Explicaci%C3%B3n%20te%C3%B3rica%20y%20entrega%20de%20Manual%20de%20Usuario%0A%20%20%20%20Estudiante-%3E%3ESistema%3A%20Demostraci%C3%B3n%20de%20registro%20guiado%0A%20%20%20%20Operador-%3E%3ESistema%3A%20Ejecuci%C3%B3n%20pr%C3%A1ctica%20aut%C3%B3noma%20de%20registro%0A%20%20%20%20Sistema--%3E%3EOperador%3A%20Muestra%20constancia%20generada%20con%20%C3%A9xito%0A%20%20%20%20Operador-%3E%3EEstudiante%3A%20Validaci%C3%B3n%20y%20firma%20de%20Acta%20de%20Capacitaci%C3%B3n%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=i('<hr><h2 id="📑-capitulo-iv-pruebas-de-aceptacion-uat-y-acta-de-entrega" tabindex="-1">📑 CAPÍTULO IV: Pruebas de Aceptación (UAT) y Acta de Entrega <a class="header-anchor" href="#📑-capitulo-iv-pruebas-de-aceptacion-uat-y-acta-de-entrega" aria-label="Permalink to &quot;📑 CAPÍTULO IV: Pruebas de Aceptación (UAT) y Acta de Entrega&quot;">​</a></h2><p>La fase de implantación culmina formalmente con la firma del <strong>Acta de Entrega y Recepción del Sistema</strong>:</p><ol><li><strong>Pruebas de Aceptación del Usuario (UAT):</strong> Los líderes comunitarios ejecutan tareas típicas y firman su conformidad con que el sistema cumple con lo solicitado en el diagnóstico inicial.</li><li><strong>Acta de Entrega del Software:</strong> Documento formal que certifica la fecha de instalación, el inventario de componentes entregados (código fuente en CD/pendrive, base de datos y manuales) y los acuerdos de garantía y soporte académico.</li></ol><hr><h2 id="📝-conclusiones-y-entregables-de-la-evaluacion-2" tabindex="-1">📝 Conclusiones y Entregables de la Evaluación 2 <a class="header-anchor" href="#📝-conclusiones-y-entregables-de-la-evaluacion-2" aria-label="Permalink to &quot;📝 Conclusiones y Entregables de la Evaluación 2&quot;">​</a></h2><p>Para la Evaluación 2 del Trimestre VI, el equipo presentará el <strong>Informe de Implantación y Capacitación</strong>:</p><ol><li>Documento del <strong>Plan de Implantación</strong> detallando la estrategia seleccionada y la configuración de red.</li><li><strong>Registro Fotográfico y Asistencia:</strong> Lista de firmas de los miembros de la comunidad que participaron en los talleres de capacitación.</li><li><strong>Copia del Acta de Entrega e Instalación:</strong> Firmada y sellada por las autoridades de la comunidad.</li></ol>',8))])}const C=c(p,[["render",m]]);export{I as __pageData,C as default};
